@layer components {
  [data-slot="alert"][data-tone="success"] {
    --alert-tone: var(--vh-success);
    --alert-tone-text: var(--vh-text-success, var(--vh-success));
  }

  [data-slot="alert"][data-tone="warning"] {
    --alert-tone: var(--vh-warning);
    --alert-tone-text: var(--vh-text-warning, var(--vh-warning));
  }

  [data-slot="alert"][data-tone="error"] {
    --alert-tone: var(--vh-error);
    --alert-tone-text: var(--vh-text-error, var(--vh-error));
  }

  [data-slot="alert"][data-tone="info"] {
    --alert-tone: var(--vh-info);
    --alert-tone-text: var(--vh-text-info, var(--vh-info));
  }

  /* Alert: an 8px box with a tinted fill and a 1px inner ring, an icon, the content, and actions. */
  [data-slot="alert"] {
    --alert-fill: color-mix(in oklab, var(--vh-bg-muted) 50%, transparent);
    --alert-ring: var(--vh-border-accented);
    align-items: flex-start;
    background: var(--alert-fill);
    border-radius: var(--vh-radius);
    box-shadow: inset 0 0 0 1px var(--alert-ring);
    color: var(--vh-text);
    display: flex;
    gap: 0.5rem;
    overflow: hidden;
    padding: 0.75rem;
    position: relative;
    width: 100%;
  }

  [data-slot="alert"]:not([data-tone="neutral"]) {
    --alert-fill: color-mix(in oklab, var(--alert-tone) 10%, transparent);
    --alert-ring: color-mix(in oklab, var(--alert-tone) 25%, transparent);
    color: var(--alert-tone-text);
  }

  [data-slot="alert"][data-variant="outline"] {
    --alert-fill: transparent;
  }

  [data-slot="alert"][data-variant="outline"][data-tone="neutral"] {
    --alert-fill: var(--vh-bg);
    --alert-ring: var(--vh-border);
  }

  [data-slot="alert"]:has(> [data-slot="alert-actions"]) {
    align-items: center;
  }

  [data-slot="alert"] > svg {
    height: 1rem;
    margin-top: 0.125rem;
    width: 1rem;
  }

  [data-slot="alert-content"] {
    display: flex;
    flex: 1;
    flex-direction: column;
    min-width: 0;
  }

  [data-slot="alert-title"] {
    font-size: 0.8125rem;
    font-weight: 500;
    line-height: 1.5;
    margin: 0;
  }

  [data-slot="alert-description"] {
    font-size: 0.75rem;
    line-height: 1.25rem;
    opacity: 0.9;
  }

  [data-slot="alert-title"] + [data-slot="alert-description"] {
    margin-top: 0.25rem;
  }

  [data-slot="alert-actions"] {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
  }

  [data-slot="alert-content"] [data-slot="alert-actions"] {
    align-self: flex-start;
    margin-top: 0.625rem;
  }

  [data-slot="alert-close"] {
    align-items: center;
    background: transparent;
    border: 0;
    border-radius: calc(var(--vh-radius) * 0.75);
    color: var(--vh-muted);
    cursor: pointer;
    display: inline-flex;
    flex: none;
    padding: 0;
  }

  @media (hover: hover) {
    [data-slot="alert-close"]:hover {
      color: var(--vh-text);
    }
  }

  [data-slot="alert-close"]:focus-visible {
    outline: 2px solid var(--vh-ring);
    outline-offset: 2px;
  }

  [data-slot="alert-close"] > svg {
    height: 1rem;
    opacity: 0.8;
    width: 1rem;
  }
}

export { default as Alert } from "./Alert.vue";
export { default as AlertActions } from "./AlertActions.vue";
export { default as AlertClose } from "./AlertClose.vue";
export { default as AlertContent } from "./AlertContent.vue";
export { default as AlertDescription } from "./AlertDescription.vue";
export { default as AlertTitle } from "./AlertTitle.vue";
export type * from "./types.ts";

export type AlertTone = "neutral" | "success" | "warning" | "error" | "info";
export type AlertVariant = "soft" | "outline";

export interface AlertProps {
  tone?: AlertTone;
  variant?: AlertVariant;
}

export interface AlertSlots {
  default?: () => unknown;
  icon?: () => unknown;
}

export interface AlertCloseProps {
  label?: string;
}

export interface AlertCloseEmits {
  close: [];
}

export interface AlertCloseSlots {
  default?: () => unknown;
}

export interface AlertContentSlots {
  default?: () => unknown;
}

export interface AlertTitleSlots {
  default?: () => unknown;
}

export interface AlertDescriptionSlots {
  default?: () => unknown;
}

export interface AlertActionsSlots {
  default?: () => unknown;
}
